    children: list[MergeCandidate] = []
    seen: set[tuple[str, str, int]] = set()

    def add_child(a: MergeCandidate, b: MergeCandidate, t: float) -> None:
        key = merge_key(a, b, t)
        if key in seen:
            return
        seen.add(key)
        children.append(merge_pair(a, b, t, generation, evaluate))

